window.CODE = Object.assign(window.CODE || {}, {"ch06/chunking.py":"\"\"\"Three ways to cut a long document into chunks before embedding it.\n\nRun:  python chunking.py\n\"\"\"\nimport re\n\nPOLICY = \"\"\"# Visitor policy\nVisiting hours for inpatient wards are 4 pm to 6 pm daily. Only two visitors are allowed per patient at a time.\nChildren under 12 may not visit the ICU. Visitors must sanitise their hands at the ward entrance.\n\n# ICU rules\nThe ICU allows one visitor at a time for 15 minutes. Mobile phones must be switched to silent.\nFlowers and outside food are not allowed in the ICU.\n\n# Emergency\nEmergency is open 24 hours. Visitors to Emergency patients wait in the family lounge on the ground floor.\"\"\"\n\n\ndef fixed_size(text: str, size: int = 120, overlap: int = 20) -> list[str]:\n    \"\"\"Cut every `size` characters, repeating `overlap` characters so no sentence is lost at a cut.\"\"\"\n    step = size - overlap\n    return [text[i:i + size] for i in range(0, len(text), step)]\n\n\ndef by_sentence(text: str, max_chars: int = 200) -> list[str]:\n    \"\"\"Group whole sentences until a chunk would exceed max_chars.\"\"\"\n    sentences = re.split(r\"(?<=[.!?])\\s+\", text.replace(\"\\n\", \" \"))\n    chunks, current = [], \"\"\n    for s in sentences:\n        if current and len(current) + len(s) > max_chars:\n            chunks.append(current.strip())\n            current = \"\"\n        current += s + \" \"\n    return chunks + ([current.strip()] if current.strip() else [])\n\n\ndef recursive(text: str, max_chars: int = 200, separators=(\"\\n# \", \"\\n\\n\", \"\\n\", \". \", \" \")) -> list[str]:\n    \"\"\"Split on the biggest natural boundary first (headings, paragraphs, lines, sentences, words),\n    and only go smaller when a piece is still too long. Keeps related text together.\"\"\"\n    text = text.strip()\n    if len(text) <= max_chars:\n        return [text] if text else []\n    for sep in separators:\n        if sep not in text:\n            continue\n        parts = text.split(sep)\n        if sep == \"\\n# \":                       # keep the heading marker on each section\n            parts = [parts[0]] + [\"# \" + p for p in parts[1:]]\n        elif sep == \". \":                        # keep the full stop on each sentence\n            parts = [p + \".\" for p in parts[:-1]] + [parts[-1]]\n        joiner = \"\\n\" if sep.startswith(\"\\n\") else \" \"\n        chunks, current = [], \"\"\n        for p in parts:                          # pack neighbouring parts together while they fit\n            if current and len(current) + len(joiner) + len(p) > max_chars:\n                chunks += recursive(current, max_chars, separators)\n                current = p\n            else:\n                current = current + joiner + p if current else p\n        return chunks + recursive(current, max_chars, separators)\n    return [text[i:i + max_chars] for i in range(0, len(text), max_chars)]\n\n\nif __name__ == \"__main__\":\n    for name, fn in [(\"Fixed size (120, overlap 20)\", fixed_size), (\"By sentence\", by_sentence), (\"Recursive\", recursive)]:\n        chunks = fn(POLICY)\n        print(f\"\\n=== {name}: {len(chunks)} chunks ===\")\n        for c in chunks:\n            print(f\"  [{len(c):>3}] {c[:90].replace(chr(10), ' / ')}{'...' if len(c) > 90 else ''}\")\n","ch06/faiss_compare.py":"\"\"\"FAISS index types compared: exact (Flat) vs approximate (HNSW, IVF).\n\nUses synthetic vectors grouped around topics (like real embeddings, where similar texts\nsit close together), so it runs offline in seconds and needs no API key.\nRun:  pip install faiss-cpu numpy\n      python faiss_compare.py\n\"\"\"\nimport time\n\nimport faiss\nimport numpy as np\n\nN, DIM, QUERIES, K = 50_000, 384, 200, 10\nrng = np.random.default_rng(42)\ntopics = rng.standard_normal((500, DIM))                       # 500 \"topics\"\ndata = (topics[rng.integers(500, size=N)] + 0.5 * rng.standard_normal((N, DIM))).astype(\"float32\")\nqueries = (topics[rng.integers(500, size=QUERIES)] + 0.5 * rng.standard_normal((QUERIES, DIM))).astype(\"float32\")\nfaiss.normalize_L2(data)           # normalised vectors: inner product == cosine similarity\nfaiss.normalize_L2(queries)\n\n\ndef run(name: str, index, train: bool = False):\n    t = time.perf_counter()\n    if train:\n        index.train(data)          # IVF must learn its clusters first\n    index.add(data)\n    build = time.perf_counter() - t\n    t = time.perf_counter()\n    _, ids = index.search(queries, K)\n    per_query_ms = (time.perf_counter() - t) / QUERIES * 1000\n    return name, build, per_query_ms, ids\n\n\nflat = run(\"Flat (exact)\", faiss.IndexFlatIP(DIM))\ntruth = flat[3]\nhnsw_index = faiss.IndexHNSWFlat(DIM, 32, faiss.METRIC_INNER_PRODUCT)\nhnsw_index.hnsw.efSearch = 64      # higher = more accurate, slower\nquantizer = faiss.IndexFlatIP(DIM)\nivf_index = faiss.IndexIVFFlat(quantizer, DIM, 256, faiss.METRIC_INNER_PRODUCT)\nivf_index.nprobe = 16              # clusters searched per query: higher = more accurate, slower\nresults = [flat, run(\"HNSW\", hnsw_index), run(\"IVF\", ivf_index, train=True)]\n\nprint(f\"{N:,} vectors of {DIM} dimensions, {QUERIES} queries, top {K}\\n\")\nprint(f\"{'index':<14} {'build s':>8} {'ms/query':>9} {'recall@10':>10}\")\nfor name, build, ms, ids in results:\n    recall = np.mean([len(set(a) & set(b)) / K for a, b in zip(ids, truth)])\n    print(f\"{name:<14} {build:>8.2f} {ms:>9.3f} {recall:>10.0%}\")\nprint(\"\\nRecall = share of the true top 10 (from Flat) that the index also found.\")\n","ch06/faq.py":"\"\"\"Made-up City Clinic FAQ entries used by every Chapter 6 script.\"\"\"\n\nFAQ = [\n    {\"id\": \"faq-01\", \"dept\": \"general\", \"text\": \"OPD runs Monday to Saturday, 9 am to 1 pm and 4 pm to 7 pm. It is closed on Sundays.\"},\n    {\"id\": \"faq-02\", \"dept\": \"general\", \"text\": \"Visiting hours for inpatient wards are 4 pm to 6 pm daily. Only two visitors per patient.\"},\n    {\"id\": \"faq-03\", \"dept\": \"billing\", \"text\": \"We accept PM-JAY (Ayushman Bharat) cards at the insurance desk on the ground floor.\"},\n    {\"id\": \"faq-04\", \"dept\": \"billing\", \"text\": \"Refunds for cancelled procedures are processed within 7 working days to the original payment method.\"},\n    {\"id\": \"faq-05\", \"dept\": \"cardiology\", \"text\": \"For an ECG or echo test, bring your previous reports and the doctor's referral slip.\"},\n    {\"id\": \"faq-06\", \"dept\": \"cardiology\", \"text\": \"Dr Mehta and Dr Rao are our cardiologists. Book through the helpdesk or the front desk.\"},\n    {\"id\": \"faq-07\", \"dept\": \"paediatrics\", \"text\": \"Children's vaccinations are given on Tuesdays and Fridays from 10 am to noon.\"},\n    {\"id\": \"faq-08\", \"dept\": \"general\", \"text\": \"Free parking is available in the basement. Two-wheelers park near gate 2.\"},\n    {\"id\": \"faq-09\", \"dept\": \"emergency\", \"text\": \"Emergency is open 24 hours. For chest pain or breathing trouble, come to Emergency or call 108.\"},\n    {\"id\": \"faq-10\", \"dept\": \"billing\", \"text\": \"Itemised bills can be collected from the billing counter or downloaded from the patient portal.\"},\n    {\"id\": \"faq-11\", \"dept\": \"general\", \"text\": \"The hospital pharmacy near the main lobby is open from 8 am to 10 pm.\"},\n    {\"id\": \"faq-12\", \"dept\": \"orthopaedics\", \"text\": \"Physiotherapy sessions after knee or hip surgery are booked through the orthopaedics desk.\"},\n]\n\n# Questions with the FAQ entry that answers them. Used to measure retrieval quality.\nLABELLED_QUERIES = [\n    (\"When is the outpatient department open?\", \"faq-01\"),\n    (\"Can my family visit me in the ward in the evening?\", \"faq-02\"),\n    (\"Do you take Ayushman Bharat?\", \"faq-03\"),\n    (\"How long until I get my money back for a cancelled operation?\", \"faq-04\"),\n    (\"What should I carry for my heart test?\", \"faq-05\"),\n    (\"Which heart specialists do you have?\", \"faq-06\"),\n    (\"When can my baby get vaccines?\", \"faq-07\"),\n    (\"Where can I leave my scooter?\", \"faq-08\"),\n    (\"My father has chest pain, what do I do?\", \"faq-09\"),\n    (\"I need a detailed bill for insurance\", \"faq-10\"),\n    (\"Is there a medical shop inside open late?\", \"faq-11\"),\n    (\"How do I book physio after my knee replacement?\", \"faq-12\"),\n]\n","ch06/hybrid_search.py":"\"\"\"Hybrid search: combine keyword search (BM25) with meaning search (embeddings).\n\nKeywords are best for exact terms (PM-JAY, ECG, gate 2); embeddings are best for meaning\n(\"my kid needs his shots\"). Reciprocal Rank Fusion (RRF) merges the two ranked lists.\n\nRun:  pip install rank-bm25 numpy\n      python hybrid_search.py\n\"\"\"\nimport re\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\nfrom rank_bm25 import BM25Okapi\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import embed  # noqa: E402\n\nfrom faq import FAQ  # noqa: E402\n\n\nSTOPWORDS = set(\"a an and are at be by can do does for from has have how i in is it its me my of on or \"\n                \"our the their there this to what when where which who will with you your\".split())\n\n\ndef words(text: str) -> list[str]:\n    \"\"\"Lower-case words without stopwords. Without this, BM25 'matches' on words like 'the' and 'for'.\"\"\"\n    return [w for w in re.findall(r\"[a-z0-9\\-]+\", text.lower()) if w not in STOPWORDS]\n\n\nclass HybridIndex:\n    def __init__(self, docs: list[dict]):\n        self.docs = docs\n        self.bm25 = BM25Okapi([words(d[\"text\"]) for d in docs])\n        v = np.array(embed([d[\"text\"] for d in docs]))\n        self.vectors = v / np.linalg.norm(v, axis=1, keepdims=True)\n\n    def keyword_rank(self, q: str) -> list[int]:\n        \"\"\"Only documents that share a word with the question. If none match, BM25 scores are all\n        zero and their order is meaningless, so it must not influence the hybrid result.\"\"\"\n        scores = self.bm25.get_scores(words(q))\n        return [int(i) for i in np.argsort(-scores) if scores[i] > 0]\n\n    def vector_rank(self, q: str) -> list[int]:\n        qv = np.array(embed([q])[0])\n        return list(np.argsort(-(self.vectors @ (qv / np.linalg.norm(qv)))))\n\n    def search(self, q: str, k: int = 3, mode: str = \"hybrid\", rrf_k: int = 60) -> list[dict]:\n        if mode == \"keyword\":\n            matched = self.keyword_rank(q)\n            order = matched + [i for i in range(len(self.docs)) if i not in matched]\n        elif mode == \"vector\":\n            order = self.vector_rank(q)\n        else:\n            # RRF: each list gives a document 1 / (rrf_k + rank). Being near the top of either list counts.\n            score = {}\n            for ranking in (self.keyword_rank(q), self.vector_rank(q)):\n                for rank, i in enumerate(ranking):\n                    score[i] = score.get(i, 0) + 1 / (rrf_k + rank + 1)\n            order = sorted(score, key=score.get, reverse=True)\n        return [self.docs[i] for i in order[:k]]\n\n\nif __name__ == \"__main__\":\n    index = HybridIndex(FAQ)\n    for q in [\"PM-JAY\", \"my kid needs his shots\", \"ECG reports\"]:\n        print(f\"\\nQ: {q}\")\n        for mode in (\"keyword\", \"vector\", \"hybrid\"):\n            top = index.search(q, k=1, mode=mode)[0]\n            print(f\"  {mode:<8} -> {top['id']}  {top['text'][:60]}\")\n","ch06/retrieval_eval.py":"\"\"\"Measure retrieval quality with labelled questions: recall@k and MRR.\n\nrecall@k  share of questions whose correct entry appears in the top k results\nMRR       mean reciprocal rank: 1 if the correct entry is first, 1/2 if second, ... averaged\nRun this whenever you change chunking, the embedding model or the search method.\n\nRun:  python retrieval_eval.py\n\"\"\"\nfrom faq import FAQ, LABELLED_QUERIES\nfrom hybrid_search import HybridIndex\n\n\ndef evaluate(index: HybridIndex, mode: str, k: int = 3) -> dict:\n    hits, rr, misses = 0, 0.0, []\n    for question, expected in LABELLED_QUERIES:\n        ids = [d[\"id\"] for d in index.search(question, k=len(FAQ), mode=mode)]\n        rank = ids.index(expected) + 1\n        hits += rank <= k\n        rr += 1 / rank\n        if rank > k:\n            misses.append((question, rank))\n    n = len(LABELLED_QUERIES)\n    return {\"mode\": mode, f\"recall@{k}\": hits / n, \"mrr\": rr / n, \"misses\": misses}\n\n\nif __name__ == \"__main__\":\n    index = HybridIndex(FAQ)\n    print(f\"{'method':<8} {'recall@3':>9} {'MRR':>6}\")\n    for mode in (\"keyword\", \"vector\", \"hybrid\"):\n        r = evaluate(index, mode)\n        print(f\"{mode:<8} {r['recall@3']:>9.0%} {r['mrr']:>6.2f}\")\n        for q, rank in r[\"misses\"]:\n            print(f\"         missed: '{q}' (correct entry ranked {rank})\")\n","ch06/similarity.py":"\"\"\"Embeddings and similarity: find the FAQ entry closest in meaning to a question.\n\nRun:  python similarity.py                (EMBEDDINGS=openai needs OPENAI_API_KEY;\n                                           EMBEDDINGS=local needs: pip install sentence-transformers)\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import embed  # noqa: E402\n\nfrom faq import FAQ  # noqa: E402\n\n\ndef cosine(a: np.ndarray, b: np.ndarray) -> np.ndarray:\n    \"\"\"Cosine similarity: 1 = same direction (same meaning), 0 = unrelated.\"\"\"\n    a = a / np.linalg.norm(a, axis=-1, keepdims=True)\n    b = b / np.linalg.norm(b, axis=-1, keepdims=True)\n    return a @ b.T\n\n\nif __name__ == \"__main__\":\n    doc_vectors = np.array(embed([f[\"text\"] for f in FAQ]))\n    print(f\"{len(FAQ)} FAQ entries -> vectors of {doc_vectors.shape[1]} numbers each\")\n    print(\"First 5 numbers of entry 1:\", np.round(doc_vectors[0][:5], 3))\n\n    questions = [\"Can I bring my scooter?\", \"Do you accept Ayushman Bharat?\", \"my kid needs his shots\"]\n    scores = cosine(np.array(embed(questions)), doc_vectors)       # one row per question\n    for q, row in zip(questions, scores):\n        best = np.argsort(-row)[:2]\n        print(f\"\\nQ: {q}\")\n        for i in best:\n            print(f\"   {row[i]:.2f}  {FAQ[i]['text']}\")\n    # Notice: no shared words between \"kid ... shots\" and \"Children's vaccinations\",\n    # yet they match. That is what embeddings add over keyword search.\n","ch06/vector_store.py":"\"\"\"A vector database with ChromaDB: store, filter by metadata, update and delete.\n\nRun:  pip install chromadb\n      python vector_store.py\nWe pass our own embeddings (from llm.embed) so the same code works with any embedding model.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nimport chromadb\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import embed  # noqa: E402\n\nfrom faq import FAQ  # noqa: E402\n\n# PersistentClient saves to disk so you embed once, not on every run.\nclient = chromadb.PersistentClient(path=str(Path(__file__).with_name(\"chroma_db\")))\nfaq = client.get_or_create_collection(\"clinic_faq\", embedding_function=None,\n                                      metadata={\"hnsw:space\": \"cosine\"})   # compare by cosine\n\n\ndef index_faq() -> None:\n    \"\"\"Add or update every FAQ entry. upsert = insert new ids, overwrite existing ones.\"\"\"\n    faq.upsert(ids=[f[\"id\"] for f in FAQ], documents=[f[\"text\"] for f in FAQ],\n               metadatas=[{\"dept\": f[\"dept\"]} for f in FAQ], embeddings=embed([f[\"text\"] for f in FAQ]))\n\n\ndef search(question: str, k: int = 3, dept: str | None = None) -> list[dict]:\n    r = faq.query(query_embeddings=embed([question]), n_results=k,\n                  where={\"dept\": dept} if dept else None)            # metadata filter\n    return [{\"id\": i, \"text\": d, \"dept\": m[\"dept\"], \"similarity\": round(1 - dist, 3)}\n            for i, d, m, dist in zip(r[\"ids\"][0], r[\"documents\"][0], r[\"metadatas\"][0], r[\"distances\"][0])]\n\n\nif __name__ == \"__main__\":\n    index_faq()\n    print(\"Entries stored:\", faq.count())\n    for hit in search(\"How do I pay with my government health card?\"):\n        print(hit)\n    print(\"\\nOnly billing entries:\")\n    for hit in search(\"Where do I go?\", k=2, dept=\"billing\"):\n        print(hit)\n    # Keep the index in sync with the source: update changed entries, delete removed ones.\n    faq.delete(ids=[\"faq-08\"])\n    print(\"\\nAfter deleting faq-08:\", faq.count(), \"entries\")\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
